contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val) public payable {
        require(true);

        // Mark the contract as initialized through the public entry point.
        c.Initialized(); if (__ESBMC_reverted()) return;

        // Read the public MinSum getter before the deciding call.
        uint beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        // The deciding call: SetMinSum must now revert because intitalized is true.
        bool reverted;
        c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General rule: after Initialized(), SetMinSum always reverts and leaves MinSum unchanged.
        assert(reverted && c.MinSum() == beforeMinSum);
    }

    receive() external payable {}
}

